    evidence_map={1:'protocol_registration.json + remote base preflight',2:'PROTOCOL/MANUSCRIPT',3:'preservation_manifest',4:'frozen animals/ABmanifest',5:'original QC hashes/native proofs',6:'native receipts false final flags',7:'PROTOCOL/METHODS',8:'protocol_registration',9:'PROTOCOL/glm/tests',10:'scientific_scores/scoring tests',11:'PROTOCOL/strict certificate',12:'coverage/selection/source',13:'protocol/null registration',14:'reuse audit/M3 exact hashes',15:'reuse audit/Nstate source hash',16:'zero old M3/offset refits',17:'all_old_baseline_fits/fixed table',18:'causal/excludes-own tests',19:'nesting/scaler/ridge tests',20:'strict originalPG/AD certificates',21:'43 regression tests',22:'all actual native role proofs',23:'execution registrations/runtime hashes',24:'all failed preflights/ACLreceipt and all model histories',25:'primary mouse_statistics',26:'bootstrap10000',27:'exact8192 signflip/Holm4',28:'matched16 full fits',29:'rate matched full fits/residual ratios',30:'nested contrasts/allSBO controls',31:'boundary20/40 full fits/13 paired',32:'probe composition/all available shared/LOPO views',33:'all4 corrected nonsignificant/complete results',34:'26x999 exact temporal invariants',35:'all104 control distributions/trial IDs',36:'MANUSCRIPT/METHODS/RESULTS',37:'primary/LOMO/CI tables',38:'all nulls/limitations',39:'METHODS/MANUSCRIPT historical failures',40:'4 scientific figures PNG/PDF + supplements',41:'A1/A2/A3',42:'A4/A5/A6',43:'A7/A8/A9/A10',44:'reproduce.ps1 + external saved reproduction receipt',45:'final_validation_freeze',46:'FINAL_VALIDATION_PLAN locked',47:'review.md + actual test/figure/claim inspection',48:'external verified Git closure receipt',49:'external verified remote/hash/clean receipt',50:'explicit no further execution after Git closure'}
